PRACTICE.push(...[{"name": "Write a tiny file", "rule": "file_write", "intro": "A variable holds a value while a program runs. A file holds named content you can open again. Here you will practise real Python file operations in a temporary browser workspace. Files reset every Run; they are not saved to your phone.", "prompt": "Use with open(\"yourname.txt\", \"w\") as a file variable. Write a nonempty string inside, then print a message outside the block.", "starter": "", "hint": "with open(\"note.txt\", \"w\") as note:\n    note.write(\"Hi\")\nprint(\"Written\")", "why": "You used write a tiny file in working Python."}, {"name": "Read what you wrote", "rule": "file_read", "intro": "Opening in \"r\" mode means read, not replace. read() returns the file content as a string. Write a practice file first, then reopen the SAME filename to read it, all in one Run.", "prompt": "Write a nonempty string to a file with \"w\". Reopen that same filename with \"r\", read its content, and print the content.", "starter": "", "hint": "with open(\"note.txt\", \"w\") as note:\n    note.write(\"Hello\")\nwith open(\"note.txt\", \"r\") as note:\n    message = note.read()\nprint(message)", "why": "You used read what you wrote in working Python."}, {"name": "Put text on new lines", "rule": "file_newline", "intro": "A newline moves the next character to a new line. Inside a Python string, backslash followed by n (\\n) represents one newline character. Use it to store several lines in one file.", "prompt": "Write a string containing \\n between two words to a file. Reopen it in \"r\" mode and print the read content.", "starter": "", "hint": "with open(\"menu.txt\", \"w\") as menu:\n    menu.write(\"Tea\\nCake\")\nwith open(\"menu.txt\", \"r\") as menu:\n    text = menu.read()\nprint(text)", "why": "You used put text on new lines in working Python."}, {"name": "Keep the old text", "rule": "file_append", "intro": "Append means add at the end without erasing what is already there. Mode \"a\" opens a file for appending. It also creates the file if it is missing.", "prompt": "Write starting text with \"w\", add different nonempty text to the same file with \"a\", then reopen with \"r\" and print the read content.", "starter": "", "hint": "with open(\"note.txt\", \"w\") as note:\n    note.write(\"Tea\")\nwith open(\"note.txt\", \"a\") as note:\n    note.write(\" and cake\")\nwith open(\"note.txt\", \"r\") as note:\n    text = note.read()\nprint(text)", "why": "You used keep the old text in working Python."}, {"name": "Read one line at a time", "rule": "file_loop", "intro": "A file can be looped over. Each turn gives the next line as text. This is useful for a list of notes without reading the whole file into one string first.", "prompt": "Create a file containing two lines using \\n. Reopen in \"r\" mode, loop over the open file and print each loop variable with end=\"\".", "starter": "", "hint": "with open(\"list.txt\", \"w\") as note:\n    note.write(\"Tea\\nCake\\n\")\nwith open(\"list.txt\", \"r\") as note:\n    for line in note:\n        print(line, end=\"\")", "why": "You used read one line at a time in working Python."}, {"name": "Count lines in a file", "rule": "file_count", "intro": "Combine a file loop with a counter. Start a count at 0, add 1 for each line, then show the count after closing the file. This counts lines, not words or characters.", "prompt": "Write a file with two lines, reopen it in \"r\", loop through it and increase a counter from 0 by 1 each turn. Print the final counter after the loop.", "starter": "", "hint": "with open(\"list.txt\", \"w\") as note:\n    note.write(\"Tea\\nCake\\n\")\ncount = 0\nwith open(\"list.txt\", \"r\") as note:\n    for line in note:\n        count = count + 1\nprint(count)", "why": "You used count lines in a file in working Python."}, {"name": "Build a tiny notebook", "rule": "file_project", "intro": "Make a two-entry notebook using the file skills you now know: write, append, reopen, then loop through the lines. Each run builds a fresh practice notebook.", "prompt": "Write one line with \"w\" and append another with \"a\" to the same file. Include \\n in each entry. Reopen with \"r\", loop over the file, and print each entry with end=\"\".", "starter": "", "hint": "with open(\"notes.txt\", \"w\") as notes:\n    notes.write(\"Learn Python\\n\")\nwith open(\"notes.txt\", \"a\") as notes:\n    notes.write(\"Practise daily\\n\")\nwith open(\"notes.txt\", \"r\") as notes:\n    for entry in notes:\n        print(entry, end=\"\")", "why": "You used build a tiny notebook in working Python."}]);
PRACTICE.push(...[{"name": "Catch a conversion error", "rule": "error_value", "intro": "An exception is a problem raised while code runs. int(\"hello\") raises ValueError. try/except lets you handle that specific problem with a useful message instead of stopping the program.", "prompt": "Use try to convert invalid whole-number text with int and print the number. Add except ValueError with a helpful printed message.", "starter": "", "hint": "try:\n    number = int(\"hello\")\n    print(number)\nexcept ValueError:\n    print(\"Use whole-number text\")", "why": "You used catch a conversion error in working Python."}, {"name": "Keep going after recovery", "rule": "error_continue", "intro": "A handled exception does not have to end the program. After try/except finishes, Python continues at the next statement outside it, whether try succeeded or the error was handled.", "prompt": "Catch ValueError from int on invalid text, print a recovery message, then print a different message outside try/except.", "starter": "", "hint": "try:\n    number = int(\"oops\")\n    print(number)\nexcept ValueError:\n    print(\"Not a whole number\")\nprint(\"Finished checking\")", "why": "You used keep going after recovery in working Python."}, {"name": "Only on success: else", "rule": "error_else", "intro": "try/except can also have else. Its block runs only when the try block finishes without an exception. Use it for work that needs a successfully converted value.", "prompt": "Convert valid whole-number text inside try. Handle ValueError with a message, and print the converted number plus 1 inside else.", "starter": "", "hint": "try:\n    number = int(\"4\")\nexcept ValueError:\n    print(\"Not a whole number\")\nelse:\n    print(number + 1)", "why": "You used only on success: else in working Python."}, {"name": "Cleanup with finally", "rule": "error_finally", "intro": "finally is a block for work that must run when Python leaves try, whether it succeeded or raised an exception. It is often used for cleanup. Here a printed message makes the timing visible.", "prompt": "Use try with an invalid int conversion, except ValueError with a printed recovery, and finally with a printed cleanup message.", "starter": "", "hint": "try:\n    number = int(\"bad\")\n    print(number)\nexcept ValueError:\n    print(\"Invalid number\")\nfinally:\n    print(\"Check ended\")", "why": "You used cleanup with finally in working Python."}, {"name": "Handle a missing file", "rule": "error_file", "intro": "Reading a nonexistent file raises FileNotFoundError. You can catch that exact error and explain what happened. In this app the practice workspace resets every Run, so this example starts with no saved.txt.", "prompt": "Try reading a missing practice filename in \"r\" mode and printing its content. Catch FileNotFoundError and print a helpful message. Do not create that file first.", "starter": "", "hint": "try:\n    with open(\"saved.txt\", \"r\") as saved:\n        text = saved.read()\n    print(text)\nexcept FileNotFoundError:\n    print(\"No saved note yet\")", "why": "You used handle a missing file in working Python."}, {"name": "Handle different problems", "rule": "error_multiple", "intro": "One try can have several except blocks. Python selects the first matching handler. Invalid numeric text and division by zero are different problems, so give each a clear message.", "prompt": "Inside try, read int(input()) and print 12 divided by that number. Add separate except ValueError and except ZeroDivisionError blocks with helpful messages.", "starter": "", "hint": "try:\n    people = int(input())\n    print(12 / people)\nexcept ValueError:\n    print(\"Use whole-number text\")\nexcept ZeroDivisionError:\n    print(\"Cannot share with zero people\")", "why": "You used handle different problems in working Python."}, {"name": "A safer number reader", "rule": "error_project", "intro": "Combine input, conversion and success-only work. A good response depends on what happened: explain invalid text, or use the valid number. End with a message in either case.", "prompt": "Read int(input()) inside try. Catch ValueError with a message. In else print the converted number plus 1. Add finally with a completion message.", "starter": "", "hint": "try:\n    age = int(input(\"Whole-number age? \"))\nexcept ValueError:\n    print(\"Please use whole-number text\")\nelse:\n    print(\"Next birthday\", age + 1)\nfinally:\n    print(\"Check complete\")", "why": "You used a safer number reader in working Python."}]);
PRACTICE.push(...[{"name": "A class is a blueprint", "rule": "class_make", "intro": "A class describes a kind of object. Think of a blueprint for many name badges. An object made from that class is called an instance. Start with one shared attribute, a named value on the class.", "prompt": "Define a class with one nonempty string attribute. Create an instance using ClassName(), then print that instance attribute with dot notation.", "starter": "", "hint": "class Badge:\n    label = \"Learner\"\nbadge = Badge()\nprint(badge.label)", "why": "You used a class is a blueprint in working Python."}, {"name": "Give an object its own value", "rule": "class_attribute", "intro": "Assigning an attribute on an instance gives that object its own value. Two badges can start from the same blueprint but show different labels.", "prompt": "Create a class with a string attribute and two separate instances. Override that attribute on only the first instance, then print the attribute on both instances.", "starter": "", "hint": "class Badge:\n    label = \"Learner\"\na = Badge()\nb = Badge()\na.label = \"Ava\"\nprint(a.label)\nprint(b.label)", "why": "You used give an object its own value in working Python."}, {"name": "Objects can do things", "rule": "class_method", "intro": "A method is a function defined inside a class. When called through an object, it receives that object as its first argument. Convention calls this parameter self.", "prompt": "Define a class with a string attribute and a no-extra-argument method that prints self.attribute. Create an instance and call its method with ().", "starter": "", "hint": "class Badge:\n    label = \"Learner\"\n    def show(self):\n        print(self.label)\nbadge = Badge()\nbadge.show()", "why": "You used objects can do things in working Python."}, {"name": "Set up each new object", "rule": "class_init", "intro": "__init__ is a special setup method. Python calls it automatically when a new instance is created. Use it to give every object its own starting data.", "prompt": "Define __init__(self, name) inside a class and store self.name = name. Create an instance with a string argument and print its stored attribute. Choose your own class, parameter and attribute names.", "starter": "", "hint": "class Badge:\n    def __init__(self, label):\n        self.label = label\nbadge = Badge(\"Ava\")\nprint(badge.label)", "why": "You used set up each new object in working Python."}, {"name": "Pass a value to a method", "rule": "class_update", "intro": "A method can receive extra arguments just like a function. self is supplied automatically; you pass the other values. Use this to change an object through a named action.", "prompt": "Use __init__ to store a string attribute. Add another method with self and one extra parameter that updates that attribute. Create an instance, call the update method with different text, then print the changed attribute.", "starter": "", "hint": "class Badge:\n    def __init__(self, label):\n        self.label = label\n    def rename(self, new_label):\n        self.label = new_label\nbadge = Badge(\"Learner\")\nbadge.rename(\"Builder\")\nprint(badge.label)", "why": "You used pass a value to a method in working Python."}, {"name": "Return from a method", "rule": "class_return", "intro": "Methods can return values, just like your earlier functions. A return sends a result to the caller. It does not display the result, so print it outside the method.", "prompt": "Use __init__ to store a string attribute. Add a no-extra-argument method returning a nonempty string joined to self.attribute. Create an instance and print the method call result.", "starter": "", "hint": "class Badge:\n    def __init__(self, label):\n        self.label = label\n    def message(self):\n        return \"Hello \" + self.label\nbadge = Badge(\"Ava\")\nprint(badge.message())", "why": "You used return from a method in working Python."}, {"name": "Keep two objects independent", "rule": "class_two", "intro": "Each call to the class creates a separate object. Attributes assigned in __init__ belong to that instance. A method called on one object changes that object, not its neighbor.", "prompt": "Define a class with __init__ storing a numeric attribute and a method adding 1 to it. Create two instances with different numeric starting values. Call the method only on the first, then print both attributes.", "starter": "", "hint": "class Counter:\n    def __init__(self, value):\n        self.value = value\n    def add(self):\n        self.value = self.value + 1\na = Counter(0)\nb = Counter(10)\na.add()\nprint(a.value)\nprint(b.value)", "why": "You used keep two objects independent in working Python."}, {"name": "Build two learning buddies", "rule": "class_project", "intro": "Bring the class ideas together: give each buddy a name, allow renaming, and return a greeting. Create two buddies and change only one, then show both greetings.", "prompt": "Define a class with __init__ storing a string name, a method updating that same attribute, and a no-extra-argument method returning a string joined to it. Make two instances with different strings, update only the first, then print the greeting method result for both.", "starter": "", "hint": "class Buddy:\n    def __init__(self, name):\n        self.name = name\n    def rename(self, name):\n        self.name = name\n    def greeting(self):\n        return \"Hi \" + self.name\na = Buddy(\"Ava\")\nb = Buddy(\"Sam\")\na.rename(\"Mira\")\nprint(a.greeting())\nprint(b.greeting())", "why": "You used build two learning buddies in working Python."}]);
PRACTICE.push(...[{"name": "A list of records", "rule": "record_make", "intro": "A record groups facts about one thing. A dictionary can be a record for one book, while a list holds several book records in order. You already know both containers; now put one inside the other.", "prompt": "Store a list containing at least two dictionaries. Each must have a string title and positive numeric pages. Print the list.", "starter": "", "hint": "books = [{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}]\nprint(books)", "why": "You used a list of records in working Python."}, {"name": "Pick a field in a record", "rule": "record_read", "intro": "Use a list index to choose a record, then a dictionary key to choose its field. These are two separate lookups, like finding a folder then reading its label.", "prompt": "Create at least two book dictionaries in a list. Print the first record's title using [0][\"title\"].", "starter": "", "hint": "books = [{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}]\nprint(books[0][\"title\"])", "why": "You used pick a field in a record in working Python."}, {"name": "Visit every record", "rule": "record_loop", "intro": "Loop directly over the list to receive one dictionary each turn. The loop variable is now a whole record, so use a key to read a field from it.", "prompt": "Create at least two book records. Loop over the list and print each record's title using the loop variable.", "starter": "", "hint": "books = [{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}]\nfor book in books:\n    print(book[\"title\"])", "why": "You used visit every record in working Python."}, {"name": "Add and update records", "rule": "record_update", "intro": "append adds a new dictionary to the list. A field assignment changes one existing record. Combining these lets a catalogue grow and change.", "prompt": "Create two or more book records. Change the first record's pages to a different positive number, append a new valid record, then print the changed pages and list length.", "starter": "", "hint": "books = [{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}]\nbooks[0][\"pages\"] = 25\nbooks.append({\"title\": \"Moon\", \"pages\": 40})\nprint(books[0][\"pages\"])\nprint(len(books))", "why": "You used add and update records in working Python."}, {"name": "Select records by a field", "rule": "record_filter", "intro": "An if inside a record loop can choose matching books. Compare a numeric field to a limit, then show only the records that meet it.", "prompt": "Create at least two book records with numeric pages, including one above 25 and one at or below 25. Loop over them and print titles only inside if book[\"pages\"] > 25.", "starter": "", "hint": "books = [{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}]\nfor book in books:\n    if book[\"pages\"] > 25:\n        print(book[\"title\"])", "why": "You used select records by a field in working Python."}, {"name": "Total the pages", "rule": "record_total", "intro": "A running total can add a numeric field from every record. Start at 0, add the pages on each turn, then print once after the loop.", "prompt": "Create at least two book records. Start a total at 0, loop through them, add each pages field to the total, and print the final total outside the loop.", "starter": "", "hint": "books = [{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}]\ntotal = 0\nfor book in books:\n    total = total + book[\"pages\"]\nprint(total)", "why": "You used total the pages in working Python."}]);
PRACTICE.push(...[{"name": "Import a toolbox", "rule": "module_import", "intro": "A module is reusable Python code grouped under a name. import makes a module available to your program. The standard library includes modules supplied with Python; no package installation is needed for these lessons.", "prompt": "Import math and print math.sqrt applied to any positive numeric literal.", "starter": "", "hint": "import math\nprint(math.sqrt(9))", "why": "You used import a toolbox in working Python."}, {"name": "Round up with ceil", "rule": "module_ceil", "intro": "math.ceil returns the smallest integer that is not below a number. For a positive partial amount, it rounds upward. This helps when you need enough whole containers.", "prompt": "Import math, store a positive item count and a positive capacity, and print math.ceil(items / capacity) using your two variables.", "starter": "", "hint": "import math\nitems = 7\ncapacity = 3\nprint(math.ceil(items / capacity))", "why": "You used round up with ceil in working Python."}, {"name": "Import one tool by name", "rule": "module_from", "intro": "from module import tool brings one named tool into your program directly. Then call that tool without the module prefix. This is another import style, not another kind of function.", "prompt": "Use from math import sqrt, then print sqrt applied to a positive numeric literal without a math prefix.", "starter": "", "hint": "from math import sqrt\nprint(sqrt(16))", "why": "You used import one tool by name in working Python."}, {"name": "Give a module a nickname", "rule": "module_alias", "intro": "as assigns an alias, a different local name for an imported module. The module itself does not change. A short alias can help when used clearly and consistently.", "prompt": "Import math with your own alias. Print the aliased module's sqrt of a positive numeric literal.", "starter": "", "hint": "import math as maths\nprint(maths.sqrt(25))", "why": "You used give a module a nickname in working Python."}, {"name": "Turn records into JSON text", "rule": "module_dumps", "intro": "JSON is a text format for exchanging simple data. json.dumps converts a Python value such as your list of records into JSON text. This is called serialization: turning data into text that can be stored or passed on.", "prompt": "Import json, create at least two valid book records, convert the list with json.dumps, store the returned string and print it.", "starter": "", "hint": "import json\nbooks = [{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}]\ntext = json.dumps(books)\nprint(text)", "why": "You used turn records into json text in working Python."}, {"name": "Get records back from JSON", "rule": "module_loads", "intro": "json.loads reads JSON text and reconstructs the corresponding Python data. A list of records can make a round trip: Python list to JSON string and back to a Python list.", "prompt": "Import json. Make at least two book records, serialize them with dumps, decode that text with loads, and print the first restored record's title.", "starter": "", "hint": "import json\nbooks = [{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}]\ntext = json.dumps(books)\nrestored = json.loads(text)\nprint(restored[0][\"title\"])", "why": "You used get records back from json in working Python."}]);
PRACTICE.push(...[{"name": "Project: a reading tracker", "rule": "project_store", "intro": "Build a small reading tracker in stages, not one giant leap. It will store book records, total their pages, accept one new book, and make a JSON file round trip. First give the tracker its own list using a class.", "prompt": "Define a tracker class with __init__ receiving and storing a book list. Create an instance with at least two valid book records, then print its first book title.", "starter": "", "hint": "class Tracker:\n    def __init__(self, books):\n        self.books = books\ntracker = Tracker([{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}])\nprint(tracker.books[0][\"title\"])", "why": "You used project: a reading tracker in working Python."}, {"name": "Project: total method", "rule": "project_total", "intro": "Add a method that totals the pages in the tracker's records. It combines a method, a list loop, dictionary lookup, a running total and return. All those pieces were introduced earlier.", "prompt": "Build a tracker storing a list of at least two book records. Add a no-extra-argument method that totals pages from self.books and returns the total after its loop. Print the instance method result.", "starter": "", "hint": "class Tracker:\n    def __init__(self, books):\n        self.books = books\n    def total_pages(self):\n        total = 0\n        for book in self.books:\n            total = total + book[\"pages\"]\n        return total\ntracker = Tracker([{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}])\nprint(tracker.total_pages())", "why": "You used project: total method in working Python."}, {"name": "Project: add a valid book", "rule": "project_add", "intro": "Now read a title and a whole-number page count. Handle invalid number text, reject nonpositive counts with if, and append a record only on success. The sample answers are Moon and 40.", "prompt": "Build a tracker with a stored book list and an add method appending title/pages. Read title, then int(input()) pages in try. Catch ValueError. In else, add only if pages > 0 and print the new list length; otherwise print a helpful message.", "starter": "", "hint": "class Tracker:\n    def __init__(self, books):\n        self.books = books\n    def add(self, title, pages):\n        self.books.append({\"title\": title, \"pages\": pages})\ntracker = Tracker([{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}])\ntitle = input()\ntry:\n    pages = int(input())\nexcept ValueError:\n    print(\"Use whole-number pages\")\nelse:\n    if pages > 0:\n        tracker.add(title, pages)\n        print(len(tracker.books))\n    else:\n        print(\"Pages must be positive\")", "why": "You used project: add a valid book in working Python."}, {"name": "Project: a JSON file round trip", "rule": "project_file", "intro": "Practise saving and reloading the tracker data within one program. Serialize the records, write the JSON text, reopen the same file, and decode its text. The temporary file still resets on the next Run.", "prompt": "Import json and create at least two book records. Write json.dumps(records) to a practice file with \"w\". Reopen the same file with \"r\", decode its read text with json.loads, then print the first restored title.", "starter": "", "hint": "import json\nbooks = [{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}]\nwith open(\"books.json\", \"w\") as saved:\n    saved.write(json.dumps(books))\nwith open(\"books.json\", \"r\") as saved:\n    restored = json.loads(saved.read())\nprint(restored[0][\"title\"])", "why": "You used project: a json file round trip in working Python."}, {"name": "Final project: your tracker", "rule": "project_final", "intro": "Put the stages together. A tracker object stores books and provides add and total methods. Read one new book, handle conversion and positive-page validation, write and reload JSON, then list the restored books and total pages.", "prompt": "Combine the previous stages: import json; define a tracker class storing books, an add(title, pages) method and a returning page-total method. Start with two book records. Read title then pages, catch ValueError and add only positive pages. Write tracker records as JSON, reload into a new tracker, loop over its books to print title and pages, and print its total method result. Supply title then page text. Use the hint as a complete starting example.", "starter": "", "hint": "import json\nclass Tracker:\n    def __init__(self, books):\n        self.books = books\n    def add(self, title, pages):\n        self.books.append({\"title\": title, \"pages\": pages})\n    def total_pages(self):\n        total = 0\n        for book in self.books:\n            total = total + book[\"pages\"]\n        return total\ntracker = Tracker([{\"title\": \"Sky\", \"pages\": 20}, {\"title\": \"Sea\", \"pages\": 30}])\ntitle = input()\ntry:\n    pages = int(input())\nexcept ValueError:\n    print(\"Use whole-number pages\")\nelse:\n    if pages > 0:\n        tracker.add(title, pages)\n    else:\n        print(\"Pages must be positive\")\nwith open(\"books.json\", \"w\") as saved:\n    saved.write(json.dumps(tracker.books))\nwith open(\"books.json\", \"r\") as saved:\n    restored = Tracker(json.loads(saved.read()))\nfor book in restored.books:\n    print(book[\"title\"], book[\"pages\"])\nprint(\"Total pages\", restored.total_pages())", "why": "You used final project: your tracker in working Python."}]);
function renderPractice(index = practiceIndex) {
  practiceIndex = index;
  navView = 'play';
  const card = PRACTICE[index];
  app.innerHTML = `<div class="view">${topbarHTML()}<div class="pad">
    <div class="pg-title">Practice, your way</div><div class="pg-sub">Practice the idea, not the spelling of a sample message.</div>
    <div class="practice-tabs"><button class="btn small" id="guided">Guided</button><button class="btn small ghost" id="free">Free code</button></div>
    <label class="step-kicker" for="skill-search">FIND A SKILL</label><input id="skill-search" class="skill-search" type="search" placeholder="Search 91 skills: loops, files, classes..." autocomplete="off"><label class="visually-hidden" for="skill">Choose a skill</label>
    <select id="skill" class="skill-select">${PRACTICE.map((c,i)=>`<option value="${i}" ${i===index?'selected':''}>${i+1}. ${c.name}</option>`).join('')}</select>
    <div class="practice-intro"><strong>${card.name}</strong><p>${card.intro}</p></div>
    <div class="step-prompt">${card.prompt}</div>
    <div class="editor-wrap"><div class="code-head"><span class="fname">practice.py</span></div><textarea id="practice-editor" class="editor" spellcheck="false" autocapitalize="off" autocomplete="off">${esc(card.starter)}</textarea></div>
    <div class="pg-actions"><button class="btn run-btn" id="practice-run">Run & check</button><button class="btn ghost" id="practice-hint">Hint</button></div>
    <div id="practice-buddy"></div><div id="practice-help" class="practice-feedback" hidden></div><div id="practice-output"></div>
  </div>${navHTML('play')}</div>`;
  bindNav();
  $('#skill').onchange = e => renderPractice(+e.target.value);
  $('#skill-search').oninput=e=>{
    const query=e.target.value.toLowerCase().trim().replace(/\bclasses\b/g,'class').replace(/\bdictionaries\b/g,'dictionar').replace(/\b(loops|files|lists|strings|functions|objects|modules|imports|errors|records)\b/g,w=>w.slice(0,-1));const matches=PRACTICE.map((c,i)=>({c,i})).filter(({c})=>(c.name+' '+c.intro+' '+c.rule).toLowerCase().includes(query));
    $('#skill').innerHTML=matches.length?`<option value="" disabled selected>Choose from ${matches.length} matches</option>`+matches.map(({c,i})=>`<option value="${i}">${i+1}. ${c.name}</option>`).join(''):'<option>No matching skills</option>';
    $('#skill').disabled=!matches.length;
  };
  $('#free').onclick = renderPlayground;
  $('#guided').onclick = () => $('#practice-editor').focus();
  $('#practice-hint').onclick = () => { const e=$('#practice-help');e.hidden=false;e.className='practice-feedback';e.textContent='One example. You can choose your own message:\n'+card.hint; };
  $('#practice-run').onclick = async () => {
    const btn=$('#practice-run'), ed=$('#practice-editor'), help=$('#practice-help');
    if (!ed.value.trim()) { help.hidden=false;help.textContent='Write a little code first, or tap Hint for an example.';return; }
    btn.disabled=true;btn.textContent='Running...';$('#practice-buddy').innerHTML=brickBuddy('thinking');
    const result=await runPython(ed.value,card.rule);
    if (!btn.isConnected) return;
    if(result.cancelled){btn.disabled=false;btn.textContent="Run & check";$("#practice-buddy").innerHTML="";return;}
    pyReady=!!pyWorker;
    $('#practice-output').innerHTML=consoleHTML(result.out,result.ok?null:friendlyErr(result.err));
    const ok=result.ok && result.concept?.ok;
    help.hidden=false;help.className='practice-feedback '+(ok?'pass':'retry');
    help.textContent=ok?'You got the idea! '+card.why:result.ok?result.concept?.feedback||'Try the hint.':friendlyErr(result.err);
    ed.blur();help.scrollIntoView({behavior:'smooth',block:'center'});
    playSound(ok?'correct':'retry');$('#practice-buddy').innerHTML=brickBuddy(ok?(correctCombo>=3?'combo':'happy'):'oops');btn.disabled=false;btn.textContent='Run & check';
  };
}
